/// <summary>
/// Specification class for advanced filtering of Systems.
/// </summary>
public class SystemAdvancedSpecification : Specification<Domain.Entities.System>
{
    public SystemAdvancedSpecification(SystemAdvancedFilter filter)
    {
        DateTime today = DateTime.UtcNow;
        var todayrange = today.GetDateRange(SystemListView.TODAY.ToString(), filter.CurrentUser?.LocalTimeOffset ?? TimeSpan.Zero);
        var last30daysrange = today.GetDateRange(SystemListView.LAST_30_DAYS.ToString(), filter.CurrentUser?.LocalTimeOffset ?? TimeSpan.Zero);

        Query.Where(q => q.Name != null)
             .Where(filter.Keyword, !string.IsNullOrEmpty(filter.Keyword))
             .Where(q => q.CreatedBy == filter.CurrentUser.UserId, filter.ListView == SystemListView.My && filter.CurrentUser is not null)
             .Where(x => x.Created >= todayrange.Start && x.Created < todayrange.End.AddDays(1), filter.ListView == SystemListView.TODAY)
             .Where(x => x.Created >= last30daysrange.Start, filter.ListView == SystemListView.LAST_30_DAYS)
             // Advanced filtering options
             .Where(x => x.Category == filter.Category, !string.IsNullOrEmpty(filter.Category))
             .Where(x => x.Status == filter.Status, !string.IsNullOrEmpty(filter.Status))
             .Where(x => x.HostingCurrent == filter.HostingCurrent, !string.IsNullOrEmpty(filter.HostingCurrent))
             .Where(x => x.CotsCustom == filter.CotsCustom, !string.IsNullOrEmpty(filter.CotsCustom))
             .Where(x => x.Type == filter.Type, !string.IsNullOrEmpty(filter.Type))
             .Where(x => x.InsourceOutsource == filter.InsourceOutsource, !string.IsNullOrEmpty(filter.InsourceOutsource))
             .Where(x => x.OwnerId == filter.OwnerId, !string.IsNullOrEmpty(filter.OwnerId));
    }
}